class CircularBuffer {
    private final Queue<Integer> queue = new ArrayDeque<>();
    private final int capacity;
    CircularBuffer(int capacity) { this.capacity = capacity; }

    void add(int x) {
        if (queue.size() == capacity) queue.poll();
        queue.offer(x);
    }
}

