Map<Character, Integer> counts = new HashMap<>();
for (String t : tasks) counts.merge(t.charAt(0), 1, Integer::sum);

PriorityQueue<Map.Entry<Character, Integer>> pq = new PriorityQueue<>(
        (a, b) -> b.getValue() - a.getValue());
