Queue<Map.Entry<Character, Integer>> cooling = new LinkedList<>(); // (task, czas powrotu)
Map<Map.Entry<Character, Integer>, Integer> returnTime = new HashMap<>();
int time = 0;
Queue<Object[]> waiting = new LinkedList<>(); // {char, pozostalaLiczba, czasPowrotu}

// uproszczona wersja: symulacja krok po kroku
Map<Character, Integer> remaining = new HashMap<>(counts);
Map<Character, Integer> availableAt = new HashMap<>();
int totalTime = 0;
int tasksLeft = tasks.length;
while (tasksLeft > 0) {
    char best = 0;
    int bestCount = -1;
    for (Map.Entry<Character, Integer> e : remaining.entrySet()) {
        if (e.getValue() > 0 && availableAt.getOrDefault(e.getKey(), 0) <= totalTime) {
            if (e.getValue() > bestCount) { bestCount = e.getValue(); best = e.getKey(); }
        }
    }
    if (bestCount == -1) {
        totalTime++;
        continue;
    }
    remaining.merge(best, -1, Integer::sum);
    availableAt.put(best, totalTime + cooldown + 1);
    tasksLeft--;
    totalTime++;
}
System.out.println("Minimalna liczba jednostek czasu: " + totalTime);

