class LRUCache {
    private final int capacity;
    private final Map<Integer, String> data = new HashMap<>();
    private final LinkedList<Integer> usageOrder = new LinkedList<>();

    LRUCache(int capacity) { this.capacity = capacity; }

    String get(int key) {
        if (!data.containsKey(key)) return null;
        usageOrder.remove((Integer) key);
        usageOrder.addLast(key);
        return data.get(key);
    }

    void put(int key, String value) {
        if (data.containsKey(key)) {
            usageOrder.remove((Integer) key);
        } else if (data.size() >= capacity) {
            int oldest = usageOrder.removeFirst();
            data.remove(oldest);
        }
        data.put(key, value);
        usageOrder.addLast(key);
    }
}

