class Agent {
    String name; int freeAt;
    Agent(String name) { this.name = name; this.freeAt = 0; }
}

Queue<String> calls = new LinkedList<>();
for (int i = 1; i <= 10; i++) calls.offer("Polaczenie" + i);
int[] callDurations = {5, 3, 8, 2, 6, 4, 7, 3, 5, 6};

PriorityQueue<Agent> agents = new PriorityQueue<>(Comparator.comparingInt(a -> a.freeAt));
agents.offer(new Agent("Agent1"));
agents.offer(new Agent("Agent2"));
agents.offer(new Agent("Agent3"));

int totalWait = 0;
int index = 0;
while (!calls.isEmpty()) {
    String call = calls.poll();
    Agent agent = agents.poll();
    int waitTime = agent.freeAt;
    totalWait += waitTime;
    int duration = callDurations[index++];
    agent.freeAt += duration;
    System.out.println(call + " -> " + agent.name + ", oczekiwanie: " + waitTime + "min");
    agents.offer(agent);
}
System.out.println("Sredni czas oczekiwania: " + (totalWait / 10.0) + "min");
